from django.utils.text import slugify


def fill_service_slugs(apps, schema_editor):
    Service = apps.get_model("landing", "Service")
    used = set()
    for service in Service.objects.all().order_by("id"):
        base = slugify(service.title, allow_unicode=True)[:150] or f"service-{service.pk}"
        slug = base
        n = 2
        while slug in used:
            slug = f"{base}-{n}"
            n += 1
        used.add(slug)
        service.slug = slug
        service.save(update_fields=["slug"])


